def filter_occupied_intervals(occupiedIntervals,freeStart,freeEnd):
    occupiedIntervals=sorted(occupiedIntervals);merged=[]
    for left,right in occupiedIntervals:
        if merged and left<=merged[-1][1]+1:merged[-1][1]=max(merged[-1][1],right)
        else:merged.append([left,right])
    answer=[]
    for left,right in merged:
        if left<freeStart:answer.append([left,min(right,freeStart-1)])
        if right>freeEnd:answer.append([max(left,freeEnd+1),right])
    return answer

